import Complex128Array = require( '@stdlib/array/complex128' );
import zcircshift = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const x = new Complex128Array( 10 );

	zcircshift( x.length, 2, x, 1 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );

	zcircshift( '10', 2, x, 1 ); // $ExpectError
	zcircshift( true, 2, x, 1 ); // $ExpectError
	zcircshift( false, 2, x, 1 ); // $ExpectError
	zcircshift( null, 2, x, 1 ); // $ExpectError
	zcircshift( undefined, 2, x, 1 ); // $ExpectError
	zcircshift( [], 2, x, 1 ); // $ExpectError
	zcircshift( {}, 2, x, 1 ); // $ExpectError
	zcircshift( ( x: number ): number => x, 2, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Complex128Array( 10 );

	zcircshift( x.length, '2', x, 1 ); // $ExpectError
	zcircshift( x.length, true, x, 1 ); // $ExpectError
	zcircshift( x.length, false, x, 1 ); // $ExpectError
	zcircshift( x.length, null, x, 1 ); // $ExpectError
	zcircshift( x.length, undefined, x, 1 ); // $ExpectError
	zcircshift( x.length, [], x, 1 ); // $ExpectError
	zcircshift( x.length, {}, x, 1 ); // $ExpectError
	zcircshift( x.length, ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a Complex128Array...
{
	const x = new Complex128Array( 10 );

	zcircshift( x.length, 2, 10, 1 ); // $ExpectError
	zcircshift( x.length, 2, '10', 1 ); // $ExpectError
	zcircshift( x.length, 2, true, 1 ); // $ExpectError
	zcircshift( x.length, 2, false, 1 ); // $ExpectError
	zcircshift( x.length, 2, null, 1 ); // $ExpectError
	zcircshift( x.length, 2, undefined, 1 ); // $ExpectError
	zcircshift( x.length, 2, [], 1 ); // $ExpectError
	zcircshift( x.length, 2, {}, 1 ); // $ExpectError
	zcircshift( x.length, 2, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const x = new Complex128Array( 10 );

	zcircshift( x.length, 2, x, '10' ); // $ExpectError
	zcircshift( x.length, 2, x, true ); // $ExpectError
	zcircshift( x.length, 2, x, false ); // $ExpectError
	zcircshift( x.length, 2, x, null ); // $ExpectError
	zcircshift( x.length, 2, x, undefined ); // $ExpectError
	zcircshift( x.length, 2, x, [] ); // $ExpectError
	zcircshift( x.length, 2, x, {} ); // $ExpectError
	zcircshift( x.length, 2, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );

	zcircshift(); // $ExpectError
	zcircshift( x.length ); // $ExpectError
	zcircshift( x.length, 2 ); // $ExpectError
	zcircshift( x.length, 2, x ); // $ExpectError
	zcircshift( x.length, 2, x, 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex128Array...
{
	const x = new Complex128Array( 10 );

	zcircshift.ndarray( x.length, 2, x, 1, 0 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );

	zcircshift.ndarray( '10', 2, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( true, 2, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( false, 2, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( null, 2, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( undefined, 2, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( [], 2, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( {}, 2, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( ( x: number ): number => x, 2, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a number...
{
	const x = new Complex128Array( 10 );

	zcircshift.ndarray( x.length, '2', x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, true, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, false, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, null, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, undefined, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, [], x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, {}, x, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, ( x: number ): number => x, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a Complex128Array...
{
	const x = new Complex128Array( 10 );

	zcircshift.ndarray( x.length, 2, 10, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, '10', 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, true, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, false, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, null, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, undefined, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, [], 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, {}, 1, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const x = new Complex128Array( 10 );

	zcircshift.ndarray( x.length, 2, x, '10', 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, true, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, false, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, null, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, undefined, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, [], 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, {}, 0 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const x = new Complex128Array( 10 );

	zcircshift.ndarray( x.length, 2, x, 1, '10' ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, true ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, false ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, null ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, undefined ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, [] ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, {} ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );

	zcircshift.ndarray(); // $ExpectError
	zcircshift.ndarray( x.length ); // $ExpectError
	zcircshift.ndarray( x.length, 2 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1 ); // $ExpectError
	zcircshift.ndarray( x.length, 2, x, 1, 0, {} ); // $ExpectError
}
